'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const {loadAllStations,normalizePage,normalizeStation}=require('./station-pages');
const origin={lat:43.3,lon:5.4},a={id:'1',lat:43.31,lon:5.41},b={id:'2',lat:43.32,lon:5.42};
const run=(fetchPage,opts={})=>loadAllStations({fetchPage,origin,radiusKm:20,...opts});
test('une page complète',async()=>{const r=await run(async()=>({stations:[a],complete:true,total:1}));assert.equal(r.status,'complete');assert.equal(r.received,1)});
test('deux pages',async()=>{const r=await run(async({cursor})=>cursor===null?{stations:[a],complete:false,nextCursor:'p2',total:2}:{stations:[b],complete:true,total:2});assert.equal(r.status,'complete');assert.equal(r.pages,2)});
test('doublon identique dédupliqué',async()=>{const r=await run(async({cursor})=>cursor===null?{stations:[a],complete:false,nextCursor:'p2'}:{stations:[a,b],complete:true});assert.equal(r.received,2)});
test('doublon conflictuel bloqué',async()=>{const r=await run(async()=>({stations:[a,{...a,lat:44}],complete:true}));assert.equal(r.status,'incomplete');assert.equal(r.reason,'duplicate_id_conflict')});
test('total annoncé incohérent',async()=>{const r=await run(async()=>({stations:[a],complete:true,total:2}));assert.equal(r.reason,'total_mismatch')});
test('total changeant',async()=>{const r=await run(async({cursor})=>cursor===null?{stations:[a],complete:false,nextCursor:'x',total:2}:{stations:[b],complete:true,total:3});assert.equal(r.reason,'total_changed')});
test('boucle curseur',async()=>{const r=await run(async()=>({stations:[a],complete:false,nextCursor:'x'}));assert.equal(r.reason,'cursor_loop')});
test('page sans indicateur complete',async()=>assert.equal((await run(async()=>({stations:[a]}))).status,'incomplete'));
test('page sans curseur',async()=>assert.equal((await run(async()=>({stations:[a],complete:false}))).status,'incomplete'));
test('page complète avec curseur refusée',()=>assert.throws(()=>normalizePage({stations:[],complete:true,nextCursor:'x'})));
test('échec réseau = incomplet',async()=>assert.equal((await run(async()=>{throw Error('offline')})).status,'incomplete'));
test('annulation préalable',async()=>{const c=new AbortController();c.abort();assert.equal((await run(async()=>{throw Error('should not run')},{signal:c.signal})).status,'cancelled')});
test('annulation pendant attente',async()=>{const c=new AbortController();const r=await run(async()=>{c.abort();return {stations:[a],complete:true}},{signal:c.signal});assert.equal(r.status,'cancelled')});
test('limite de pages',async()=>assert.equal((await run(async({cursor})=>({stations:[],complete:false,nextCursor:cursor===null?'a':'b'}),{maxPages:1})).reason,'page_limit'));
test('limite stations',async()=>assert.equal((await run(async()=>({stations:[a,b],complete:true}),{maxStations:1})).reason,'station_limit'));
test('rayon négatif rejeté',async()=>await assert.rejects(()=>run(async()=>({stations:[],complete:true}),{radiusKm:-1})));
test('origine invalide rejetée',async()=>await assert.rejects(()=>run(async()=>({stations:[],complete:true}),{origin:{lat:120,lon:1}})));
test('coordonnées invalides station',()=>assert.throws(()=>normalizeStation({id:'1',lat:99,lon:0})));
test('ID numérique normalisé',()=>assert.equal(normalizeStation({id:1,lat:0,lon:0}).id,'1'));
test('progression notifiée',async()=>{let count=0;await run(async()=>({stations:[a],complete:true}),{onProgress:()=>count++});assert.equal(count,1)});
test('réponse nulle',async()=>assert.equal((await run(async()=>null)).status,'incomplete'));
test('page vide finale et total nul',async()=>assert.equal((await run(async()=>({stations:[],complete:true,total:0}))).status,'complete'));
test('callback invalide',async()=>await assert.rejects(()=>loadAllStations({origin,radiusKm:20,fetchPage:1})));
test('curseur numérique accepté',async()=>{const r=await run(async({cursor})=>cursor===null?{stations:[a],complete:false,nextCursor:2}:{stations:[b],complete:true});assert.equal(r.received,2)});
